/**
 * The browser half of the vault v2 format proof (WIKI4AI-197 D2b).
 *
 * The vectors are not produced here. They come from
 * `mcp-server/tests/fixtures/vault_v2_golden.json`, generated by the Python
 * MCP server with fixed keys, fixed salts and fixed IVs, and asserted on its
 * side by `mcp-server/tests/test_vault_v2_golden.py`. Two implementations in
 * two languages agreeing byte-for-byte on the same fixed input is the only
 * evidence that a row MCP writes will open in this browser — and the only way
 * to catch the class of bug that has already bitten this vault once
 * (`json.dumps` with `ensure_ascii=True` writing "é" as `\u00e9`, different
 * bytes for the same characters).
 *
 * If this file fails and the fixture has not changed, the TypeScript drifted.
 */

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, it, expect, vi } from 'vitest';

import { cryptoApi } from '../services/cryptoApi';
import { bytesToBase64 } from '../services/encryptionService';
import { encodeFieldText } from '../services/vaultEntryCodec';
import {
  asV2Key,
  buildV2Aad,
  decryptV2Field,
  deriveV2Kek,
  parseV2KdfParams,
  unwrapDek,
  type VaultField,
} from '../services/vaultCrypto';

interface Golden {
  format: string;
  sha256_hex: { input: string; hex: string }[];
  pbkdf2_sha256: { password: string; salt_b64: string; iterations: number; key_hex: string }[];
  json_text: { value: string; utf8_hex: string }[];
  aad: {
    user_id: number;
    entry_uuid: string;
    field: VaultField;
    key_id: string;
    utf8_hex: string;
  }[];
  field: {
    name: string;
    dek_hex: string;
    iv_hex: string;
    user_id: number;
    entry_uuid: string;
    field: VaultField;
    key_id: string;
    value: string;
    packed_b64: string;
  }[];
  wrap: { kek_hex: string; iv_hex: string; dek_hex: string; wrapped_b64: string }[];
  kdf_params: { kdf_json: string; iterations: number; key_bytes: number };
}

const FIXTURE = join(
  dirname(fileURLToPath(import.meta.url)),
  '..',
  '..',
  '..',
  'mcp-server',
  'tests',
  'fixtures',
  'vault_v2_golden.json',
);

const golden = JSON.parse(readFileSync(FIXTURE, 'utf8')) as Golden;

function bytesFromHex(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

function bytesFromBase64(base64: string): Uint8Array {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

function concat(a: Uint8Array, b: Uint8Array): Uint8Array {
  const out = new Uint8Array(a.length + b.length);
  out.set(a, 0);
  out.set(b, a.length);
  return out;
}

describe('vault v2 golden vectors (Python MCP ⇄ TypeScript)', () => {
  it('reads the vectors the Python server generated', () => {
    expect(golden.format).toBe('w4ai-vault-v2-golden/1');
  });

  it('hashes the master password the same way', async () => {
    for (const vector of golden.sha256_hex) {
      const digest = await cryptoApi.sha256(new TextEncoder().encode(vector.input));
      expect(toHex(digest)).toBe(vector.hex);
    }
  });

  it('derives keys with the same PBKDF2', async () => {
    for (const vector of golden.pbkdf2_sha256) {
      const key = await cryptoApi.deriveKey(
        vector.password,
        bytesFromBase64(vector.salt_b64),
        vector.iterations,
      );
      expect(toHex(key)).toBe(vector.key_hex);
    }
  });

  it('derives the v2 KEK from the raw password identically', async () => {
    const vector = golden.pbkdf2_sha256[2];
    const kek = await deriveV2Kek(vector.password, bytesFromBase64(vector.salt_b64), vector.iterations);
    expect(toHex(kek)).toBe(vector.key_hex);
  });

  it('writes the same plaintext bytes — JSON.stringify and raw UTF-8', () => {
    for (const vector of golden.json_text) {
      // encodeFieldText is this client's writer; the fixture came from Python.
      expect(toHex(encodeFieldText(vector.value))).toBe(vector.utf8_hex);
      // And the naive expectation is spelled out for the diacritic case,
      // because that is the one json.dumps got wrong.
      if (vector.value.includes('é') || vector.value.includes('š')) {
        expect(vector.utf8_hex).not.toContain('5c7530'); // no \uXXXX escaping
      }
    }
  });

  it('builds the same AAD', () => {
    for (const vector of golden.aad) {
      const aad = buildV2Aad({
        userId: vector.user_id,
        entryUuid: vector.entry_uuid,
        field: vector.field,
        keyId: vector.key_id,
      });
      expect(toHex(aad)).toBe(vector.utf8_hex);
    }
  });

  it('seals a field into the same Base64 blob', async () => {
    for (const vector of golden.field) {
      const iv = bytesFromHex(vector.iv_hex);
      const aad = buildV2Aad({
        userId: vector.user_id,
        entryUuid: vector.entry_uuid,
        field: vector.field,
        keyId: vector.key_id,
      });
      const { ciphertextWithTag } = await cryptoApi.encryptBytes(encodeFieldText(vector.value), bytesFromHex(vector.dek_hex), {
        iv,
        aad,
      });
      expect(bytesToBase64(concat(iv, ciphertextWithTag))).toBe(vector.packed_b64);
    }
  });

  it('opens the blob the Python server sealed', async () => {
    for (const vector of golden.field) {
      const plaintext = await decryptV2Field(vector.packed_b64, asV2Key(bytesFromHex(vector.dek_hex)), {
        userId: vector.user_id,
        entryUuid: vector.entry_uuid,
        field: vector.field,
        keyId: vector.key_id,
      });
      expect(plaintext).not.toBeNull();
      expect(JSON.parse(new TextDecoder().decode(plaintext ?? new Uint8Array()))).toBe(vector.value);
    }
  });

  it('wraps and unwraps the DEK identically', async () => {
    for (const vector of golden.wrap) {
      const kek = bytesFromHex(vector.kek_hex);
      const iv = bytesFromHex(vector.iv_hex);
      const dek = bytesFromHex(vector.dek_hex);
      const { ciphertextWithTag } = await cryptoApi.encryptBytes(dek, kek, { iv });
      expect(bytesToBase64(concat(iv, ciphertextWithTag))).toBe(vector.wrapped_b64);
      const opened = await unwrapDek(kek, vector.wrapped_b64);
      expect(toHex(opened ?? new Uint8Array())).toBe(vector.dek_hex);
    }
  });

  it('parses the server KDF parameters the same way', () => {
    expect(parseV2KdfParams(golden.kdf_params.kdf_json)).toEqual({
      iterations: golden.kdf_params.iterations,
      keyBytes: golden.kdf_params.key_bytes,
    });
  });

  /**
   * The same vectors through the *other* browser branch.
   *
   * `cryptoApi` has two implementations behind one interface: WebCrypto in a
   * secure context, @noble in plain HTTP. Every current deployment is plain
   * HTTP, so the noble branch is the one that actually ships — and it is a
   * third implementation of the same format, which makes it a third chance to
   * disagree with Python. Checking only the WebCrypto branch would leave the
   * deployed path unproven.
   */
  it('agrees with Python through the non-WebCrypto fallback too', async () => {
    const realSubtle = globalThis.crypto.subtle;
    vi.resetModules();
    Object.defineProperty(globalThis.crypto, 'subtle', { value: undefined, configurable: true });
    let fallback: typeof cryptoApi;
    try {
      ({ cryptoApi: fallback } = await import('../services/cryptoApi'));

      for (const vector of golden.pbkdf2_sha256.slice(0, 2)) {
        const key = await fallback.deriveKey(vector.password, bytesFromBase64(vector.salt_b64), vector.iterations);
        expect(toHex(key)).toBe(vector.key_hex);
      }

      for (const vector of golden.field.slice(0, 4)) {
        const iv = bytesFromHex(vector.iv_hex);
        const aad = buildV2Aad({
          userId: vector.user_id,
          entryUuid: vector.entry_uuid,
          field: vector.field,
          keyId: vector.key_id,
        });
        const { ciphertextWithTag } = await fallback.encryptBytes(encodeFieldText(vector.value), bytesFromHex(vector.dek_hex), {
          iv,
          aad,
        });
        expect(bytesToBase64(concat(iv, ciphertextWithTag))).toBe(vector.packed_b64);

        const opened = await fallback.decryptBytes(
          bytesFromBase64(vector.packed_b64).slice(12),
          iv,
          bytesFromHex(vector.dek_hex),
          aad,
        );
        expect(opened).not.toBeNull();
        expect(JSON.parse(new TextDecoder().decode(opened ?? new Uint8Array()))).toBe(vector.value);
      }
    } finally {
      Object.defineProperty(globalThis.crypto, 'subtle', { value: realSubtle, configurable: true });
      vi.resetModules();
    }
  });

  it('the fixture still covers the cases that broke between languages', () => {
    const values = golden.json_text.map((vector) => vector.value);
    expect(values.some((value) => /[éš]/.test(value))).toBe(true);
    expect(values.some((value) => value.includes('\u{1F600}'))).toBe(true);
    expect(values.some((value) => /\uD800/.test(value))).toBe(true);
    expect(values.some((value) => value.includes('\u0000'))).toBe(true);
    expect(values).toContain('');
    const fields = new Set(golden.field.map((vector) => vector.field));
    expect([...fields].sort()).toEqual(['notes', 'password', 'username']);
  });
});
